import React, { useState, useEffect } from 'react';
import { TrendingUp, Zap } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';

import { logger } from '@/lib/logger';
const CACHE_KEY = 'live_counter_cache';
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

interface CachedCount {
  count: number;
  timestamp: number;
}

export function LiveCounter() {
  const [count, setCount] = useState<number | null>(() => {
    try {
      const cached = localStorage.getItem(CACHE_KEY);
      if (cached) {
        const { count, timestamp }: CachedCount = JSON.parse(cached);
        if (Date.now() - timestamp < CACHE_DURATION) {
          return count;
        }
      }
    } catch (e) {
      // Ignore parse errors
    }
    return null;
  });

  useEffect(() => {
    // If we have a valid cached count, skip the network request entirely
    if (count !== null) return;

    // Defer the fetch so it doesn't extend the critical request chain
    const timer = setTimeout(async () => {
      try {
        const { count: dbCount, error } = await supabase
          .from('analyses')
          .select('*', { count: 'exact', head: true });

        if (!error && dbCount !== null) {
          setCount(dbCount);
          localStorage.setItem(CACHE_KEY, JSON.stringify({
            count: dbCount,
            timestamp: Date.now(),
          }));
        }
      } catch (e) {
        logger.error('Failed to fetch analysis count:', e);
      }
    }, 2000); // Delay 2s to avoid blocking critical path

    return () => clearTimeout(timer);
  }, [count]);

  // If count is low or unknown, show "early adopter" messaging
  if (count === null || count < 100) {
    return (
      <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-success/10 border border-success/20">
        <TrendingUp className="w-4 h-4 text-success" />
        <span className="text-sm font-medium text-success">
          Now analyzing ideas in 50+ cities
        </span>
      </div>
    );
  }

  return (
    <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-success/10 border border-success/20">
      <TrendingUp className="w-4 h-4 text-success" />
      <span className="text-sm font-medium text-success">
        {count.toLocaleString()} businesses analyzed
      </span>
    </div>
  );
}
